52		report := traceOf(t, `{"datasets":[
53			{"name":"T","upstreams":["M"]},
54			{"name":"M","upstreams":["a","Z"]},
55			{"name":"a","upstreams":[]},
56			{"name":"Z","upstreams":[]}
