		{"name":"T","upstreams":["B","A"]},
		{"name":"A","upstreams":["Z"]},
		{"name":"Z","upstreams":["M"]},
		{"name":"B","upstreams":["C"]},
		{"name":"C","upstreams":["M"]},
		{"name":"M","upstreams":["R2","R1"]},
		{"name":"R1","upstreams":[]},
		{"name":"R2","upstreams":[]},
		{"name":"U","upstreams":["X"]},
		{"name":"X","upstreams":[]}
	]}`
	shuffled := `{ "datasets" : [
		{"upstreams":[],"name":"X"},
		{"name":"U","upstreams":["X","X"]},
		{"upstreams":[],"name":"R2"},
		{"name":"R1","upstreams":[]},
		{"upstreams":["R1","R2","R1"],"name":"M"},
		{"name":"C","upstreams":["M","M"]},
		{"upstreams":["M"],"name":"Z"},
		{"name":"B","upstreams":["C"]},
		{"name":"A","upstreams":["Z"]},
		{"upstreams":["A","B","B","A"],"name":"T"}
	] }`

	s1 := snapshotForTrace(t, deepGraph)
	s2 := snapshotForTrace(t, shuffled)

	out1, stderr, exit := captureStdout(t, func() int { return run([]string{"trace", s1, "T"}) })
	if exit != 0 {
